def comps_of(g,bg):
    seen=set(); out=[]
    R,C=len(g),len(g[0])
    for r in range(R):
        for c in range(C):
            if (r,c) in seen or g[r][c]==bg: continue
            col=g[r][c]; st=[(r,c)]; comp=set()
            while st:
                a,b=st.pop()
                if (a,b) in seen or not(0<=a<R and 0<=b<C) or g[a][b]!=col: continue
                seen.add((a,b)); comp.add((a,b))
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        if dr==dc==0: continue
                        st.append((a+dr,b+dc))
            out.append(comp)
    return out
