def backtrack(groups, H, W, k=0, used=set(), acc=[]):
    results=[]
    def rec(k,used,acc):
        if k==len(groups):
            results.append(acc.copy())
            return True
        v,p=groups[k]
        for dr,dc,ts in enumerate_trans((v,p),H,W):
            if any(t in used for t in ts): continue
            used.add(*ts)
            rec(k+1,used,acc+[ (v,dr,dc)])
            used.discard(*ts)
        return False
    rec(k,used,acc)
    return results

