    groups={k:[p for p in d[k] if p not in framepts] for k in sorted(set(d)-{v})}
    sols=[]
    def rec(k,used,acc):
        if k==len(groups):
            sols.append(acc.copy()); return True
        for v,ps in groups.items():
            if k!=len([g for g in groups if g<v]): continue
        # find next group key
        keys=sorted(groups,key=lambda kv:(kv,groups[kv]))
        pass
    # simpler backtracking over sorted group keys
    keys=sorted(groups.keys())
    def rec(k,used,acc):
        if k==len(keys):
            sols.append(acc.copy()); return True
        vg=keys[k]; ps=groups[vg]
        for dr in range(-H,H+1):
            for dc in range(-W,W+1):
                ts=tuple(sorted(((i+dr)%h,(j+dc)%w) for i,j in ps))
                if any(t in used for t in ts): continue
                rec(k+1,used|set(ts),acc+[(vg,dr,dc)])
        return False
    rec(0,set(),[])
    return fr,(h,w),groups,sols

