def solve(I, verbose=False):
    H,W=len(I),len(I[0])
    bgc=Counter(v for row in I for v in row).most_common(1)[0][0]
    objs={v:[(r,c) for r in range(H) for c in range(W) if I[r][c]==v] for v in set(x for row in I for x in row)-{bgc}}
    # frame color: exactly 4 cells forming rectangle corners
    frame=None; fb=None
    for v,ps in objs.items():
        if v==bgc: continue
        r0,r1,c0,c1=box(ps)
        if len(ps)==4 and all(p in ps for p in [(r0,c0),(r0,c1),(r1,c0),(r1,c1)]):
            frame=v; fb=(r0,r1,c0,c1); break
    r0,r1,c0,c1=fb
    Ht,Wt=r1-r0+1,c1-c0+1
    out=[[frame]*Wt for _ in range(Ht)]
    info=[]
    for v,ps in objs.items():
        if v==frame or not ps: continue
        nr0,nr1,nc0,nc1=box(ps)
        rel={(a-nr0,b-nc0) for a,b in ps}
        h,w=nr1-nr0+1,nc1-nc0+1
        off=(nr0-r0,nc0-c0)  # where object sits relative to frame origin
        # candidate placements: any (dr,dc) where shape fits inside out and doesn't overlap frame-color cells
        cands=[]
        for dr in range(-h+1,Ht-h+1):
            for dc in range(-w+1,Wt-w+1):
                pl={(dr+a,dc+b) for a,b in rel}
                if all(0<=a<Ht and 0<=b<Wt and out[a][b]==bgc for a,b in pl):
                    cands.append((dr,dc))
        # pick candidate minimizing distance from original offset (dr,dc == off means shape sits at its original place)
        best=min(cands,key=lambda o:(abs(o[0]-off[0])+abs(o[1]-off[1]), o[0]**2+o[1]**2))
        for a,b in rel: out[best[0]+a][best[1]+b]=v
        info.append((v,off,best,rel))
    return out,info
